271	        submitTranslation(docId, "s1", "en", "alice", "hello", 1, newRequestId());
272	        approve(docId, "s1", "en", "bob", 1, newRequestId());
273	        updateTerms(docId, 0, RULES_V1, newRequestId());
274	
275	        // 术语过期 422（当前草稿版本 3）
276	        assertThat(publish(docId, 3, 0, newRequestId()).status()).isEqualTo(422);
277	
278	        // 重新提交仍违反术语规则：提交侧 422，译文未被覆盖，发布侧依旧拦截
279	        ApiResult violated = submitTranslation(docId, "s1", "en", "alice", "hello v2", 1, newRequestId());
280	        assertThat(violated.status()).isEqualTo(422);
281	        assertThat(publish(docId, 3, 0, newRequestId()).status()).isEqualTo(422);
282	
283	        // 合规提交并批准后发布成功
284	        submitTranslation(docId, "s1", "en", "alice", "machine learning", 1, newRequestId());
285	        approve(docId, "s1", "en", "bob", 2, newRequestId());
286	        assertThat(publish(docId, 4, 0, newRequestId()).status()).isEqualTo(201);
287	    }
288	}
